function terrainAlong(terrain,a,b){const out=new Set(),d=dist(a,b),steps=Math.max(1,Math.ceil(d/.25));for(let i=0;i<=steps;i++){const q=i/steps,x=a.x+(b.x-a.x)*q,y=a.y+(b.y-a.y)*q;for(const e of terrainAt(terrain,x,y))out.add(e);}return out;}
function baseOverlapsTerrainZone(u,z,x=u.x,y=u.y,facing=u.facing??0){const ghost={...u,x,y,facing},corners=rectCornersAt(ghost,x,y,facing),samples=[{x,y},...corners];if(z.parts?.length){for(const part of z.parts){if(part.closed&&part.points.length>=3&&samples.some(p=>pointInPoly(p.x,p.y,part.points)))return true;if(!part.closed){for(let i=1;i<part.points.length;i++){const a=part.points[i-1],b=part.points[i],near=nearestPointOnSegmentForRoad({x,y},a,b),radius=footprintRadiusToward(ghost,near);if(pointSegDistance(x,y,a,b)<=radius+(z.cls==='Road'?.18:.14))return true;}}}return false;}return samples.some(p=>terrainContains(z,p.x,p.y));}
