function baseSize(u){const s=footprintSpec(u,{unitBaseMm:50,unitBaseWidthMm:50,unitBaseDepthMm:50,commanderBaseMm:25});return Math.max(s.width,s.depth);}
function baseFrontage(u){return footprintSpec(u,{unitBaseMm:50,unitBaseWidthMm:50,unitBaseDepthMm:50,commanderBaseMm:25}).width;}
function baseDepthSize(u){return footprintSpec(u,{unitBaseMm:50,unitBaseWidthMm:50,unitBaseDepthMm:50,commanderBaseMm:25}).depth;}
function forwardVec(facing){const r=(facing??0)*Math.PI/180;return{x:Math.sin(r),y:-Math.cos(r)};}
function rightVec(facing){const r=(facing??0)*Math.PI/180;return{x:Math.cos(r),y:Math.sin(r)};}
function rectCornersAt(u,x=u.x,y=u.y,facing=u.facing??0){return footprintPolygon(u,x,y,facing,{unitBaseMm:50,unitBaseWidthMm:50,unitBaseDepthMm:50,commanderBaseMm:25});}
function footprintInsideBounds(u,x=u.x,y=u.y,facing=u.facing??0,ctx){return footprintInsideBattlefield(u,ctx.width,ctx.height,x,y,facing,{unitBaseMm:50,unitBaseWidthMm:50,unitBaseDepthMm:50,commanderBaseMm:25});}
function rotatedPointAround(point,pivot,deg){const r=deg*Math.PI/180,c=Math.cos(r),sn=Math.sin(r),dx=point.x-pivot.x,dy=point.y-pivot.y;return{x:pivot.x+dx*c-dy*sn,y:pivot.y+dx*sn+dy*c};}
function frontCornersAt(u,x=u.x,y=u.y,facing=u.facing??0){return sharedFrontCorners(u,x,y,facing,{unitBaseMm:50,unitBaseWidthMm:50,unitBaseDepthMm:50,commanderBaseMm:25});}
function wheelTransform(u,signedDelta){if(Math.abs(signedDelta)<1e-9)return{x:u.x,y:u.y,facing:u.facing??0,pivot:null};const corners=frontCornersAt(u),pivot=signedDelta>0?corners.right:corners.left,center=rotatedPointAround({x:u.x,y:u.y},pivot,signedDelta);return{x:center.x,y:center.y,facing:normDeg((u.facing??0)+signedDelta),pivot};}
