      if(hit<=1e-6){const probeDistance=Math.min(distance,.01),l=distance||1,probe={...startGhost,x:a.x+dir.x/l*probeDistance,y:a.y+dir.y/l*probeDistance};if(!rectOverlapAt(probe,probe.x,probe.y,o))continue;}
