function enemyTooCloseAt(u,x,y,ctx){const ghost={...u,x,y};return ctx.units.some(o=>!o.destroyed&&!o.inactive&&coalition(o.faction)!==coalition(u.faction)&&baseGapDistance(ghost,o)<1*ctx.scale-1e-4);}
