function commandTest(unit,ctx){const cr=commandRuleConfig(ctx),threshold=cr?.mode==='rating-proximity'?Number(cr.testThreshold||5):(unit.traits.includes('Elite')?3:4),cb=commandBonus(unit,ctx),die=ctx.rng.d6(),roll=die+cb.bonus,ok=roll>=threshold;ctx.event('command_test',unit,{die,bonus:cb.bonus,bonusFrom:cb.commander?.name||null,bonusKind:cb.kind,commandRating:cb.commander?.commandRating??null,distance:cb.commander?Number(baseGapDistance(unit,cb.commander).toFixed(2)):null,range:cb.range||null,roll,threshold,outcome:ok?'pass':'fail'});return ok;}
